"""12359: geometry files for the sub-orbifolds of the non-SUSY Z6-II space group (Z2(Witten) x Z6, lattice Z6-II_1) generated by the
Witten element and theta^s (s = 2: torus e5e6 fixed; s = 3: torus e3e4 fixed).  s = 1 regenerates the parent and is the known-positive
control (its spectrum must equal the shipped geometry's).  Constructing elements: Lambda / ((1 - theta^k) Lambda + Lambda^{theta^k}) modulo
the sub point group (fixed-torus windings are massive); centralizer generators: the Witten element, the fixed-lattice translations and,
for each sub power i, (theta^{s i}, m) with (1 - theta^k) m = (1 - theta^{s i}) l when integrally solvable (plane by plane)."""
import sys, itertools
import numpy as np
from fractions import Fraction as F
P = [np.array([[1, -1], [1, 0]]), np.array([[0, -1], [1, -1]]), -np.eye(2, dtype=int)]
def mp(A, k):
    return np.linalg.matrix_power(A, k)
def plane_reps(p, k):
    M = np.eye(2, dtype=int) - mp(P[p], k)
    if not M.any():
        return [(0, 0)], M
    d = round(abs(np.linalg.det(M)))
    reps = []
    for v in itertools.product(range(-3, 4), repeat=2):
        if all(not inL(np.array(v) - np.array(r), M) for r in reps):
            reps.append(v)
        if len(reps) == d:
            break
    reps.sort(key=lambda v: (abs(v[0]) + abs(v[1]), [-x for x in v]))
    return reps, M
def inL(v, M):
    if not M.any():
        return True
    x = np.linalg.solve(M.astype(float), v.astype(float))
    return np.allclose(x, np.round(x))
def rot(l, k):
    return np.concatenate([mp(P[p], k) @ l[2 * p:2 * p + 2] for p in range(3)])
def equiv(l1, l2, k):
    return all(inL(l1[2 * p:2 * p + 2] - l2[2 * p:2 * p + 2], np.eye(2, dtype=int) - mp(P[p], k)) for p in range(3))
def solve_m(l, k, i):
    rhs = l - rot(l, i); m = []
    for p in range(3):
        M = np.eye(2, dtype=int) - mp(P[p], k); r = rhs[2 * p:2 * p + 2]
        if not M.any():
            if r.any():
                return None
            m += [0, 0]; continue
        x = np.linalg.solve(M.astype(float), r.astype(float))
        if not np.allclose(x, np.round(x)):
            return None
        m += [int(round(t)) for t in x]
    return m
def row(a, j, l):
    return f'{a} {j} 0 ' + ' '.join(str(int(x)) for x in l) + ' '
def build(s, head):
    N = 6 // s
    sectors, cent = [], []
    for a in (0, 1):
        for j in range(N):
            k = (s * j) % 6
            per = [plane_reps(p, k)[0] for p in range(3)]
            reps = []
            for combo in itertools.product(*per):
                l = np.array([x for v in combo for x in v])
                if not any(equiv(rot(l, s * i), r, k) for r in reps for i in range(N)):
                    reps.append(l)
            sectors.append([row(a, j, l) for l in reps])
            for l in reps:
                gens = []
                if k == 0:
                    gens += [row(0, 0, np.eye(6, dtype=int)[t]) for t in range(6)] + [row(0, 1, np.zeros(6))]
                else:
                    for p in range(3):
                        if not (np.eye(2, dtype=int) - mp(P[p], k)).any():
                            for t in (0, 1):
                                e = np.zeros(6, dtype=int); e[2 * p + t] = 1; gens.append(row(0, 0, e))
                    for i in range(1, N):
                        m = solve_m(l, k, s * i)
                        if m is not None:
                            gens.append(row(0, i, m))
                gens.append(row(1, 0, np.zeros(6)))
                cent.append((row(a, j, l), gens))
    tw = ' '.join(str(F(s, 6) * c) if F(s, 6) * c != 0 else '0' for c in (1, 2, -3))
    out = head.replace('@N@', str(N)).replace('@TWIST@', '0/1 ' + tw)
    out += 'begin constructing elements\n' + ''.join('new sector\n' + ''.join(r + '\n' for r in sec) for sec in sectors) + 'end constructing elements\n\n'
    out += 'begin centralizer elements\n' + ''.join(f'// Const elem: {c} \nbegin data\n' + ''.join(g + '\n' for g in gs) + 'end data\n\n' for c, gs in cent)
    out += 'end centralizer elements\n'
    return out, [len(x) for x in sectors]
if __name__ == '__main__':
    s = int(sys.argv[1])
    src = open(sys.argv[2]).read()
    head = src.split('begin constructing elements')[0]
    head = head.replace('point group\n2\n6\n1', 'point group\n2\n@N@\n1').replace(' 0/1 1/6 1/3 -1/2', ' @TWIST@')
    if s == 2:
        head = head.replace('allowed order of Wilson lines\n1\n1\n3\n3\n2\n2', 'allowed order of Wilson lines\n3\n3\n3\n3\n2\n2').replace('begin identical WLs\n 3 4', 'begin identical WLs\n 1 2\n 3 4')
    if s == 3:
        head = head.replace('allowed order of Wilson lines\n1\n1\n3\n3\n2\n2', 'allowed order of Wilson lines\n2\n2\n3\n3\n2\n2').replace('begin identical WLs\n 3 4\n', 'begin identical WLs\n')
    out, sizes = build(s, head)
    open(sys.argv[3], 'w', newline='\n').write(out)
    print('s', s, 'sector sizes', sizes)
